proc hello_orcad {} { puts "Capture session ready" }
hello_orcad

;; report every component and its XY location
procedure( comp_loc()
  let( (design)
    design = axlDBGetDesign()
    foreach( comp design->components
      printf("%s  %L\n" comp->refdes comp->xy)
    )
  )
)
comp_loc()
